# Build replacement text for each lesson id
for lid, segments in new_transcripts.items():
    # Find the existing transcript block and replace it
    # Pattern: transcript: [ ... ]
    # We'll match from 'transcript: [' to the next '{' that starts the next lesson
    # Better approach: match the entire transcript array content
    
    # Build new JS array text
    lines = ['transcript: [']
    for pct, text in segments:
        escaped = text.replace("'", "\\'").replace('ó', 'ó').replace('í', 'í').replace('á', 'á').replace('é', 'é').replace('ú', 'ú').replace('ñ', 'ñ')
        # Actually, we need the original accented chars. Let's just use raw text.
        lines.append(f"  {{ pct: {pct:.4f}, text: '{text}' }},")
    lines.append('],')
    new_block = '\n          '.join(lines)
    
    # Find the old transcript block - from 'transcript: [' to the next '],' that closes it
    # Use regex to find transcript: [ ... ],
    pattern = rf"({lid}',\s*\n\s*transcript: )\[.*?\]"
    
    # We need to be more specific. Let me find by unique context around each transcript
    # Actually, let me just match the transcript block by lesson id context
    
    old_pattern = lid + "',\n"
    idx = html.find(old_pattern)
    if idx > 0:
        # Find 'transcript: [' after this
        t_idx = html.find("transcript: [", idx)
        if t_idx > 0:
            # Find the closing '],' of the transcript array
            # Count brackets to find the match
            start = t_idx + len("transcript: [")
            depth = 1
            pos = start
            while depth > 0 and pos < len(html):
                if html[pos] == '[':
                    depth += 1
                elif html[pos] == ']':
                    depth -= 1
                pos += 1
            end = pos  # position after ']'
            
            # Now replace html[t_idx:end+1] with new_block
            html = html[:t_idx] + new_block + html[end:]

